/* Generated from file_page.html. */
static const char FILE_PAGE[] = "<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>IGW 双总线文件交换</title>\n<style>:root{font-family:system-ui,sans-serif;color:#17333e;background:#f1f5f7}body{margin:0}main{max-width:960px;margin:32px auto;padding:0 20px}header{padding:12px 0}h1{font-size:28px;margin:8px 0}h2{font-size:18px;margin-top:0}p{line-height:1.6}section{background:white;border:1px solid #d8e4e8;border-radius:12px;padding:22px;margin:16px 0}label{display:inline-block;margin:6px 20px 6px 0}button,select,input{font:inherit;border:1px solid #b8cbd1;border-radius:6px;padding:9px}button{background:#086879;color:white;cursor:pointer;margin:6px 8px 6px 0}button:disabled{opacity:.45;cursor:default}input[type=number]{width:140px}.note{font-size:14px;color:#526b76}#state{white-space:pre-wrap;background:#e9f4f5;border-radius:8px;padding:14px}.bad{color:#a62525}pre{font-size:13px;overflow-wrap:anywhere;white-space:pre-wrap}article{border-top:1px solid #d8e4e8;padding:16px 0}progress{width:100%;height:20px}#cancel{background:#904329}</style>\n<main><header><span class=\"note\">IGW · R23 / SD_FILE_R23 从机</span><h1>双总线文件交换</h1><p>电脑通过以太网连接网关，选择 CAN 或 RS485 与设备交换文件。</p></header>\n<section><label>传输总线 <select id=\"bus\"><option value=\"can\">CAN · 500 kbit/s</option><option value=\"rs485\">RS485 · 115200 bit/s</option></select></label><label>设备 <select id=\"unit\"><option value=\"1\">逻辑设备 1</option><option value=\"2\">逻辑设备 2</option></select></label><p class=\"note\">每个逻辑设备有一组共享 SD 文件槽，CAN 和 RS485 访问同一份内容。单文件最大 8 MiB（8388608 字节），每次执行一个任务。</p><div id=\"state\">正在连接网关…</div></section>\n<section><h2>下发电脑文件并校验</h2><input id=\"file\" type=\"file\"><p class=\"note\">下发后自动从所选总线独立读回并比较 SHA256。新文件完成 SD 校验后提交；未完成写入保留旧版。1 MiB 的 CAN 下发与读回实测合计约 3 分 9 秒。</p><button id=\"put\">下发并读回校验</button></section>\n<section><h2>取回设备文件</h2><button id=\"get\">取回设备现有文件</button><label>测试文件字节数 <input id=\"size\" type=\"number\" min=\"0\" max=\"8388608\" value=\"4096\"></label><button id=\"generate\">设备生成并取回</button><p class=\"note\">生成测试文件完成后提交到 SD。8 MiB 取回估计 CAN 约 13 分钟、RS485 约 19 分钟，实际速度以板上结果为准。</p></section>\n<section><h2>传输进度与结果</h2><button id=\"refresh\">刷新结果</button><button id=\"cancel\" disabled>停止当前传输</button><div id=\"jobs\"></div><p class=\"note\">关闭网页不会取消任务，重新打开可查看当前会话。停止或失败后需检查日志并重启文件服务。成功文件可在此下载到电脑。文件为明文，从机使用独立 SD 卡存储；提交文件的掉电恢复需通过板上测试确认。退出主机服务时将证据复制到主机 SD 卡。</p></section></main>\n<script>\n'use strict';\nlet token='',busy=false,serverBusy=false,blocked=false,polling=false,remaining=16;const names=new Map(),el=id=>document.getElementById(id);\nfunction status(text,bad=false){el('state').textContent=text;el('state').className=bad?'bad':'';}\nfunction controls(){for(const id of ['put','get','generate'])el(id).disabled=busy||serverBusy||blocked||!token||remaining<=0;el('refresh').disabled=busy||!token;el('cancel').disabled=busy||!serverBusy||blocked||!token;for(const id of ['bus','unit','file','size'])el(id).disabled=busy||serverBusy;}\nasync function jsonResponse(r){let v;try{v=await r.json();}catch{throw Error('网关响应不完整，请刷新结果并保留日志。');}if(!r.ok||v.ok===false)throw Error(v.error||'请求失败');return v;}\nasync function download(job){if(busy||serverBusy)return;busy=true;controls();try{const r=await fetch('/api/download?id='+encodeURIComponent(job.job_id),{headers:{'X-IGW-Token':token},cache:'no-store'});if(!r.ok){await jsonResponse(r);return;}const blob=await r.blob();if(blob.size!==job.bytes)throw Error('下载长度不一致');if(globalThis.crypto&&crypto.subtle){const hash=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());const hex=Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('');if(hex!==job.sha256)throw Error('电脑端 SHA256 不一致');}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=names.get(job.job_id)||('device'+job.unit+'-'+job.job_id.slice(0,8)+'.bin');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已下载 '+job.bytes+' 字节到电脑。');}catch(e){status(e.message,true);}finally{busy=false;controls();}}\nconst phaseNames={starting:'准备',put:'下发',readback:'独立读回',get:'取回',generate:'生成并取回',verify:'校验',complete:'校验通过',failed:'失败'};\nasync function refresh(){if(polling||!token)return;polling=true;try{const d=await jsonResponse(await fetch('/api/jobs',{headers:{'X-IGW-Token':token},cache:'no-store'}));blocked=d.blocked;serverBusy=d.busy;remaining=16-d.jobs.length;el('jobs').replaceChildren();for(const j of d.jobs.slice().reverse()){const a=document.createElement('article'),title=document.createElement('strong'),detail=document.createElement('pre');title.textContent=j.bus.toUpperCase()+' · 设备 '+j.unit+' · '+j.operation+' · '+(phaseNames[j.phase]||j.phase);detail.textContent=(j.done?j.bytes+' 字节':j.progress_bytes+' / '+j.total_bytes+' 字节')+'\\nSHA256: '+(j.sha256||'完成后显示')+'\\n任务: '+j.job_id;a.append(title,detail);if(!j.done){const p=document.createElement('progress');p.max=j.total_bytes||1;p.value=j.progress_bytes;a.append(p);}if(j.ok){const b=document.createElement('button');b.textContent='下载已校验文件';b.disabled=serverBusy;b.onclick=()=>download(j);a.append(b);}el('jobs').append(a);}if(blocked)status('本会话有停止或失败的任务。请保留日志，检查接线与结果后重启文件服务。',true);else if(serverBusy)status('传输正在执行，进度每秒更新。上传任务会先下发，再独立读回校验。');else if(d.jobs.length)status('当前无传输任务。校验通过的文件可下载，剩余任务名额 '+remaining+'。');}finally{polling=false;controls();}}\nasync function transfer(op){if(busy||serverBusy||blocked)return;busy=true;controls();let body=new Uint8Array(0),size=0,name='';const unit=Number(el('unit').value),bus=el('bus').value;try{if(op==='put'){const f=el('file').files[0];if(!f)throw Error('请先选择电脑文件');if(f.size>8388608)throw Error('文件不能超过 8388608 字节（8 MiB）');body=await f.arrayBuffer();size=f.size;name=f.name||'';}else if(op==='generate'){size=Number(el('size').value);if(!Number.isInteger(size)||size<0||size>8388608)throw Error('字节数需在 0～8388608 范围内');}status('正在提交任务…');const j=await jsonResponse(await fetch('/api/file?op='+op+'&unit='+unit+'&size='+size+'&bus='+bus,{method:'POST',headers:{'X-IGW-Token':token,'Content-Type':'application/octet-stream'},body}));if(name)names.set(j.job_id,name);serverBusy=true;await refresh();}catch(e){status(e.message,true);}finally{busy=false;controls();}}\nel('put').onclick=()=>transfer('put');el('get').onclick=()=>transfer('get');el('generate').onclick=()=>transfer('generate');el('refresh').onclick=()=>refresh().catch(e=>status(e.message,true));el('cancel').onclick=async()=>{if(busy||!serverBusy)return;busy=true;controls();try{await jsonResponse(await fetch('/api/cancel',{method:'POST',headers:{'X-IGW-Token':token},body:new Uint8Array(0)}));blocked=true;status('停止请求已提交，等待总线清理；请保留日志。',true);}catch(e){status(e.message,true);}finally{busy=false;controls();}};\n(async()=>{try{const s=await jsonResponse(await fetch('/api/session',{cache:'no-store'}));token=s.token;blocked=s.blocked;serverBusy=s.busy;status('网关已连接。请选择总线、设备和文件。');await refresh();}catch(e){status(e.message,true);}controls();})();\nsetInterval(()=>{if(token&&!busy)refresh().catch(e=>status('暂时无法刷新：'+e.message,true));},1000);\n</script></html>\n";
